#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string recipe;
    cin >> recipe;

    int64 stock[3], price[3], required[3] = {};
    cin >> stock[0] >> stock[1] >> stock[2];

    for (char ingredient : recipe) {
        if (ingredient == 'B') ++required[0];
        else if (ingredient == 'S') ++required[1];
        else ++required[2];
    }

    cin >> price[0] >> price[1] >> price[2];

    int64 money;
    cin >> money;

    auto canMake = [&](int64 count) {
        i128 cost = 0;

        for (int i = 0; i < 3; ++i) {
            i128 needed = static_cast<i128>(required[i]) * count - stock[i];
            if (needed > 0) {
                cost += needed * price[i];
            }
        }

        return cost <= money;
    };

    int64 low = 0;
    int64 high = 4'000'000'000'000'000'000LL;

    while (low < high) {
        int64 mid = low + (high - low + 1) / 2;

        if (canMake(mid)) {
            low = mid;
        } else {
            high = mid - 1;
        }
    }

    cout << low << '\n';
    return 0;
}

