#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

using ll = long long;
using i128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string recipe;
    cin >> recipe;

    ll stock[3], price[3], money;
    ll need[3] = {};

    cin >> stock[0] >> stock[1] >> stock[2];

    for (char c : recipe) {
        if (c == 'B') ++need[0];
        else if (c == 'S') ++need[1];
        else if (c == 'C') ++need[2];
    }

    cin >> price[0] >> price[1] >> price[2];
    cin >> money;

    auto canMake = [&](ll count) {
        i128 cost = 0;
        for (int i = 0; i < 3; ++i) {
            i128 required = static_cast<i128>(need[i]) * count;
            if (required > stock[i]) {
                cost += (required - stock[i]) * price[i];
            }
        }
        return cost <= money;
    };

    ll low = 0, high = 1;
    while (canMake(high)) {
        low = high;
        high *= 2;
    }

    while (low + 1 < high) {
        ll mid = low + (high - low) / 2;
        if (canMake(mid))
            low = mid;
        else
            high = mid;
    }

    cout << low << '\n';
    return 0;
}

#include <iostream>
#include <string>
#include <algorithm>

using namespace std;

using ll = long long;
using i128 = __int128_t;

ll requiredIngredient[3];
ll availableIngredient[3];
ll ingredientPrice[3];
ll totalAmount;

bool canMake(ll count) {
    i128 totalCost = 0;

    for (int i = 0; i < 3; ++i) {
        i128 needed = static_cast<i128>(requiredIngredient[i]) * count;
        if (needed > availableIngredient[i]) {
            totalCost += (needed - availableIngredient[i]) * ingredientPrice[i];
        }
    }

    return totalCost <= totalAmount;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string recipe;
    cin >> recipe;
    cin >> availableIngredient[0]
        >> availableIngredient[1]
        >> availableIngredient[2];

    for (char ingredient : recipe) {
        if (ingredient == 'B') {
            ++requiredIngredient[0];
        } else if (ingredient == 'S') {
            ++requiredIngredient[1];
        } else {
            ++requiredIngredient[2];
        }
    }

    cin >> ingredientPrice[0]
        >> ingredientPrice[1]
        >> ingredientPrice[2];
    cin >> totalAmount;

    ll low = 0;
    ll high = 1;

    while (canMake(high)) {
        high *= 2;
    }

    while (low + 1 < high) {
        ll mid = low + (high - low) / 2;

        if (canMake(mid)) {
            low = mid;
        } else {
            high = mid;
        }
    }

    cout << low << '\n';
    return 0;
}

